import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import productService from '../services/productService';
import './ProductDetail.css';

function ProductDetail() {
    const { id } = useParams();
    const [product, setProduct] = useState(null);
    const [loading, setLoading] = useState(true);
    const [quantity, setQuantity] = useState(1);

    useEffect(() => {
        loadProductDetail();
    }, [id]);

    const loadProductDetail = async () => {
        try {
            setLoading(true);
            const response = await productService.getProductById(id);
            // Giả định response trả về trực tiếp data product hoặc response.data tùy thuộc vào axiosClient của bạn
            setProduct(response.data || response);
        } catch (error) {
            console.error("Lỗi khi tải chi tiết sản phẩm:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleQuantityChange = (type) => {
        if (type === 'decrease' && quantity > 1) {
            setQuantity(quantity - 1);
        } else if (type === 'increase') {
            setQuantity(quantity + 1);
        }
    };

    if (loading) {
        return (
            <div className="detail-loading">
                <div className="spinner"></div>
                <p>Đang tải thông tin sản phẩm...</p>
            </div>
        );
    }

    if (!product) {
        return (
            <div className="detail-error">
                <h2>Không tìm thấy sản phẩm!</h2>
                <Link to="/shop" className="btn-back">Quay lại cửa hàng</Link>
            </div>
        );
    }

    return (
        <div className="product-detail-page">
            {/* Breadcrumb để người dùng dễ di chuyển */}
            <div className="breadcrumb-container">
                <div className="container">
                    <p className="breadcrumb">
                        <Link to="/">Trang chủ</Link> / <Link to="/shop">Cửa hàng</Link> / <span>{product.name}</span>
                    </p>
                </div>
            </div>

            <div className="container">
                <div className="detail-layout">
                    {/* Khối hình ảnh sản phẩm */}
                    <div className="detail-image-section">
                        <div className="main-image-wrapper">
                            <img 
                                src={product.image || 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85'} 
                                alt={product.name} 
                                className="main-image"
                            />
                        </div>
                    </div>

                    {/* Khối thông tin mua hàng */}
                    <div className="detail-info-section">
                        <span className="product-category">{product.category?.name || "Nội thất"}</span>
                        <h1 className="product-title">{product.name}</h1>
                        
                        <div className="product-price-box">
                            <span className="product-price">
                                {product.price?.toLocaleString('vi-VN')}đ
                            </span>
                            {product.oldPrice && (
                                <span className="product-old-price">
                                    {product.oldPrice?.toLocaleString('vi-VN')}đ
                                </span>
                            )}
                        </div>

                        <div className="product-divider"></div>

                        <p className="product-short-description">
                            {product.shortDescription || "Sản phẩm nội thất tinh tế, mang lại không gian sống đẳng cấp, hiện đại và ấm cúng cho ngôi nhà của bạn."}
                        </p>

                        <div className="purchase-action-group">
                            <div className="quantity-selector">
                                <button onClick={() => handleQuantityChange('decrease')}>-</button>
                                <input type="number" value={quantity} readOnly />
                                <button onClick={() => handleQuantityChange('increase')}>+</button>
                            </div>

                            <button className="btn-add-to-cart">
                                Thêm vào giỏ hàng
                            </button>
                        </div>

                        <div className="product-meta">
                            <p><strong>Tình trạng:</strong> <span className="stock-status">Còn hàng</span></p>
                            <p><strong>Mã sản phẩm:</strong> SKU-{product.id || id}</p>
                        </div>
                    </div>
                </div>

                {/* Khối mô tả chi tiết phía dưới */}
                <div className="product-tabs-section">
                    <div className="tab-header">
                        <h3>Mô tả chi tiết</h3>
                    </div>
                    <div className="tab-content">
                        <p>{product.description || "Chưa có mô tả chi tiết cho sản phẩm này. Sản phẩm được sản xuất từ chất liệu cao cấp, đảm bảo độ bền và tính thẩm mỹ cao, phù hợp với mọi không gian nội thất hiện đại."}</p>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default ProductDetail;
